    def _create_share(self, name_key='name', extra_args=''):
        """Creates a locally redundant NFS file share and returns it."""
        return self.cmd(
            'fileshare create '
            '--resource-group {rg} '
            '--name {%s} '
            '--location {location} '
            '--protocol NFS '
            '--provisioned-storage-gib 100 '
            '--provisioned-iops 3000 '
            '--provisioned-throughput-mib 125 '
            '--redundancy Local %s' % (name_key, extra_args)
        ).get_output_in_json()

    @AllowLargeResponse()
    def test_fileshares_limits_show_offer(self):
        self.kwargs['location'] = LOCATION

        no_body = self.cmd('fileshare limits-show --location {location}').get_output_in_json()

        # The offer defaults to NFS on SSD, so an explicit NFS/SSD offer returns the same limits as no offer.
        explicit_offer = self.cmd(
            'fileshare limits-show --location {location} --protocol NFS --media-tier SSD',
            checks=[
                self.exists('properties.limits'),
                self.exists('properties.provisioningConstants'),
            ]
        ).get_output_in_json()
        self.assertEqual(no_body['properties']['limits'], explicit_offer['properties']['limits'])
        self.assertEqual(no_body['properties']['provisioningConstants'], explicit_offer['properties']['provisioningConstants'])

